/* alloc_stats.c - see alloc_stats.h. Do not edit this file.

   Each block gets a small header in front of it recording its size and a magic number,
   so free knows how many bytes it releases and can tell a pointer that never came from
   malloc. The magic number sits last, right before the block, so free also notices a
   write just before it. The header is padded to the alignment of the widest basic types,
   so the pointer the caller gets is aligned for any type, just like one from the real
   malloc. */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "alloc_stats.h"

void *__real_malloc(size_t size);
void *__real_calloc(size_t count, size_t size);
void __real_free(void *p);

#define MAGIC 0xA110C8EDu
#define FREED 0xDEADF4EEu

typedef union {
  struct {
    size_t size;
    unsigned epoch;
    unsigned magic;
  } info;
  long double align_ld;
  long long align_ll;
  void *align_p;
} Header;

static AllocStats stats;

/* Counts resets, so free can tell whether a block was allocated since the last one. */
static unsigned epoch = 0;
static int fail_countdown = -1;

void alloc_stats_get(AllocStats *out)
{
  *out = stats;
}

void alloc_stats_reset(void)
{
  stats.allocs = 0;
  stats.frees = 0;
  stats.bytes_allocated = 0;
  stats.new_live_bytes = 0;
  stats.peak_live_bytes = stats.live_bytes;
  epoch++;
}

void alloc_fail_after(size_t k)
{
  fail_countdown = (int)k;
}

void alloc_fail_never(void)
{
  fail_countdown = -1;
}

/* true if this allocation should fail on purpose. */
static int injected_failure(void)
{
  if (fail_countdown < 0) {
    return 0;
  }
  if (fail_countdown == 0) {
    fail_countdown = -1;
    return 1;
  }
  fail_countdown--;
  return 0;
}

/* Records h as a new live block of size bytes and returns the caller's pointer. */
static void *track(Header *h, size_t size)
{
  h->info.size = size;
  h->info.magic = MAGIC;
  h->info.epoch = epoch;
  stats.allocs++;
  stats.new_live_bytes += size;
  stats.bytes_allocated += size;
  stats.live_bytes += size;
  if (stats.live_bytes > stats.peak_live_bytes) {
    stats.peak_live_bytes = stats.live_bytes;
  }
  return h + 1;
}

/* The header of p, a pointer from track. Stops the program if p has none. */
static Header *header_of(void *p, const char *who)
{
  Header *h = (Header *)p - 1;
  if (h->info.magic != MAGIC) {
    fprintf(stderr, "alloc_stats: %s(%p): %s\n", who, p,
            h->info.magic == FREED
                ? "this block was already freed"
                : "this pointer did not come from malloc, or something wrote just before "
                  "its block");
    abort();
  }
  return h;
}

void *__wrap_malloc(size_t size)
{
  if (size > SIZE_MAX - sizeof(Header) || injected_failure()) {
    return NULL;
  }
  Header *h = __real_malloc(sizeof(Header) + size);
  return h == NULL ? NULL : track(h, size);
}

void *__wrap_calloc(size_t count, size_t size)
{
  if (size != 0 && count > (SIZE_MAX - sizeof(Header)) / size) {
    return NULL;
  }
  if (injected_failure()) {
    return NULL;
  }
  Header *h = __real_calloc(1, sizeof(Header) + count * size);
  return h == NULL ? NULL : track(h, count * size);
}

void __wrap_free(void *p)
{
  if (p == NULL) {
    return;
  }
  Header *h = header_of(p, "free");
  stats.frees++;
  stats.live_bytes -= h->info.size;
  if (h->info.epoch == epoch) {
    stats.new_live_bytes -= h->info.size;
  }
  h->info.magic = FREED;
  __real_free(h);
}

/* realloc is a new block, a copy and a free, so the counts see all three. */
void *__wrap_realloc(void *p, size_t size)
{
  if (p == NULL) {
    return __wrap_malloc(size);
  }
  size_t old = header_of(p, "realloc")->info.size;
  void *q = __wrap_malloc(size);
  if (q == NULL) {
    return NULL;
  }
  memcpy(q, p, old < size ? old : size);
  __wrap_free(p);
  return q;
}
